<script setup lang="ts">
import axios from 'axios';
import { computed, onMounted, ref, watch } from 'vue';
import IconButton from '../design-system/IconButton.vue';

type RecurrenceType = 'ONE_TIME_DATE' | 'ANNUAL_FIXED_DATE' | 'ANNUAL_NTH_WEEKDAY' | 'EASTER_OFFSET';
interface LocalityOption { id: number; name: string; abbreviation?: string; }
const props = defineProps<{ occasionId: number | null }>();
const emit = defineEmits<{ cancel: []; saved: [] }>();
type FieldErrors = Record<string, string[]>;
const loading = ref(false); const saving = ref(false); const error = ref(''); const fieldErrors = ref<FieldErrors>({}); const easterHelpOpen = ref(false);
const countries = ref<LocalityOption[]>([]); const states = ref<LocalityOption[]>([]); const municipalities = ref<LocalityOption[]>([]);
const title = computed(() => props.occasionId === null ? 'Inserindo Feriado' : 'Editando Feriado');
const form = ref({ name: '', occasionCategory: 'HOLIDAY', territorialScope: '' as '' | 'COUNTRY' | 'BRAZIL_STATE' | 'BRAZIL_MUNICIPALITY', locality: { countryId: '', brazilStateId: '', brazilMunicipalityId: '' }, validity: { from: '', to: '' }, recurrence: { type: 'ANNUAL_FIXED_DATE' as RecurrenceType, oneTimeDate: '', fixedMonth: '', fixedDay: '', weekMonth: '', weekOrdinal: 'FIRST', weekDay: 'MONDAY', easterOffsetDays: 0 } });
const icon = (name: string): string => `/assets/icons/${name}_24.png`;
function changeRecurrenceType(type: RecurrenceType): void { Object.assign(form.value.recurrence, { type, oneTimeDate: '', fixedMonth: '', fixedDay: '', weekMonth: '', weekOrdinal: 'FIRST', weekDay: 'MONDAY', easterOffsetDays: 0 }); easterHelpOpen.value = false; }
function changeScope(): void { Object.assign(form.value.locality, { countryId: '', brazilStateId: '', brazilMunicipalityId: '' }); states.value = []; municipalities.value = []; }
async function loadCountries(): Promise<void> { try { countries.value = (await axios.get('/api/v1/platform/calendar-occasion-localities/countries')).data.countries; } catch { error.value = 'Não foi possível carregar os países disponíveis. Atualize a tela e tente novamente.'; } }
async function loadStates(): Promise<void> { states.value = []; municipalities.value = []; form.value.locality.brazilStateId = ''; form.value.locality.brazilMunicipalityId = ''; if (!form.value.locality.countryId) return; try { states.value = (await axios.get(`/api/v1/platform/calendar-occasion-localities/countries/${form.value.locality.countryId}/brazil-states`)).data.states; } catch { error.value = 'Não foi possível carregar os estados disponíveis para o país selecionado.'; } }
async function loadMunicipalities(): Promise<void> { municipalities.value = []; form.value.locality.brazilMunicipalityId = ''; if (!form.value.locality.brazilStateId) return; try { municipalities.value = (await axios.get(`/api/v1/platform/calendar-occasion-localities/brazil-states/${form.value.locality.brazilStateId}/municipalities`)).data.municipalities; } catch { error.value = 'Não foi possível carregar os municípios disponíveis para o estado selecionado.'; } }
function errorsFor(field: string): string[] { return fieldErrors.value[field] ?? []; }
function fieldLabel(field: string): string { return ({ name: 'Nome', occasionCategory: 'Categoria', territorialScope: 'Abrangência', 'locality.countryId': 'País', 'locality.brazilStateId': 'Estado', 'locality.brazilMunicipalityId': 'Município', 'validity.from': 'Início da vigência', 'validity.to': 'Fim da vigência', 'recurrence.type': 'Tipo de recorrência', 'recurrence.oneTimeDate': 'Data da ocorrência', 'recurrence.fixedDay': 'Dia da data fixa', 'recurrence.fixedMonth': 'Mês da data fixa', 'recurrence.weekMonth': 'Mês do dia ordinal', 'recurrence.weekOrdinal': 'Ocorrência ordinal', 'recurrence.weekDay': 'Dia da semana', 'recurrence.easterOffsetDays': 'Deslocamento da Páscoa' } as Record<string, string>)[field] ?? field; }
function payloadForSave(): Record<string, unknown> { const payload = { ...form.value, locality: { ...form.value.locality }, validity: { ...form.value.validity }, recurrence: { ...form.value.recurrence } }; const recurrence = payload.recurrence as Record<string, unknown>; const applicable = ({ ONE_TIME_DATE: ['oneTimeDate'], ANNUAL_FIXED_DATE: ['fixedMonth', 'fixedDay'], ANNUAL_NTH_WEEKDAY: ['weekMonth', 'weekOrdinal', 'weekDay'], EASTER_OFFSET: ['easterOffsetDays'] } as Record<RecurrenceType, string[]>)[recurrence.type as RecurrenceType]; for (const field of ['oneTimeDate', 'fixedMonth', 'fixedDay', 'weekMonth', 'weekOrdinal', 'weekDay', 'easterOffsetDays']) if (!applicable.includes(field)) recurrence[field] = null; return payload; }
function describeFailure(reason: unknown, operation: 'save' | 'load'): void { fieldErrors.value = {}; const responseData = axios.isAxiosError(reason) || (typeof reason === 'object' && reason !== null && 'response' in reason) ? (reason as { response?: { data?: { error?: unknown } } }).response?.data : null; const payload = (responseData as { error?: unknown } | null)?.error ?? responseData; if (payload && typeof payload === 'object' && 'fields' in payload && typeof payload.fields === 'object' && payload.fields !== null) fieldErrors.value = Object.fromEntries(Object.entries(payload.fields).map(([field, messages]) => [field, Array.isArray(messages) ? messages.map(String) : [String(messages)]])); error.value = payload && typeof payload === 'object' && 'message' in payload && typeof payload.message === 'string' ? payload.message : operation === 'save' ? 'Não foi possível salvar a definição. Revise os campos informados e tente novamente.' : 'Não foi possível carregar esta definição.'; }
async function load(): Promise<void> { await loadCountries(); if (props.occasionId === null) return; loading.value = true; try { Object.assign(form.value, (await axios.get(`/api/v1/platform/calendar-occasions/${props.occasionId}`)).data.calendarOccasion); if (form.value.locality.countryId) states.value = (await axios.get(`/api/v1/platform/calendar-occasion-localities/countries/${form.value.locality.countryId}/brazil-states`)).data.states; if (form.value.locality.brazilStateId) municipalities.value = (await axios.get(`/api/v1/platform/calendar-occasion-localities/brazil-states/${form.value.locality.brazilStateId}/municipalities`)).data.municipalities; } catch (reason) { describeFailure(reason, 'load'); } finally { loading.value = false; } }
async function save(): Promise<void> { saving.value = true; error.value = ''; fieldErrors.value = {}; try { const payload = payloadForSave(); props.occasionId === null ? await axios.post('/api/v1/platform/calendar-occasions', payload) : await axios.patch(`/api/v1/platform/calendar-occasions/${props.occasionId}`, payload); emit('saved'); } catch (reason) { describeFailure(reason, 'save'); } finally { saving.value = false; } }
watch(() => form.value.occasionCategory, (category) => { if (category === 'COMMEMORATIVE_DATE' && form.value.territorialScope !== 'COUNTRY') { form.value.territorialScope = 'COUNTRY'; changeScope(); } });
onMounted(() => void load());
</script>

<template>
  <section class="calendar-occasion-form" aria-label="Editor de feriado">
    <header><h3>{{ title }}</h3></header>
    <form @submit.prevent="save"><div class="feedback"><p v-if="loading">Carregando definição…</p><p v-if="error" role="alert">{{ error }}</p><ul v-if="Object.keys(fieldErrors).length"><li v-for="(messages, field) in fieldErrors" :key="field"><strong>{{ fieldLabel(field) }}:</strong> {{ messages.join(' ') }}</li></ul></div>
      <div class="frame"><fieldset :disabled="loading || saving">
        <section><h4>Identificação e aplicação</h4><div class="grid"><label>Nome<input v-model="form.name" required></label><label>Categoria<select v-model="form.occasionCategory"><option value="HOLIDAY">Feriado</option><option value="OPTIONAL_DAY_OFF">Ponto facultativo</option><option value="COMMEMORATIVE_DATE">Data comemorativa</option></select></label></div>
          <div class="grid"><label>Abrangência<select v-model="form.territorialScope" required @change="changeScope"><option disabled value="">Selecione</option><option value="COUNTRY">País</option><option v-if="form.occasionCategory !== 'COMMEMORATIVE_DATE'" value="BRAZIL_STATE">Estado</option><option v-if="form.occasionCategory !== 'COMMEMORATIVE_DATE'" value="BRAZIL_MUNICIPALITY">Município</option></select></label><div class="locality-slot"><template v-if="form.territorialScope === 'COUNTRY'"><label>País<select v-model="form.locality.countryId" required><option disabled value="">Selecione</option><option v-for="item in countries" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></template><template v-else-if="form.territorialScope === 'BRAZIL_STATE'"><label>País<select v-model="form.locality.countryId" required @change="loadStates"><option disabled value="">Selecione</option><option v-for="item in countries" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Estado<select v-model="form.locality.brazilStateId" required :disabled="!form.locality.countryId"><option disabled value="">{{ form.locality.countryId ? 'Selecione' : 'Selecione primeiro o país' }}</option><option v-for="item in states" :key="item.id" :value="item.id">{{ item.abbreviation }} · {{ item.name }}</option></select></label></template><template v-else-if="form.territorialScope === 'BRAZIL_MUNICIPALITY'"><label>País<select v-model="form.locality.countryId" required @change="loadStates"><option disabled value="">Selecione</option><option v-for="item in countries" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Estado<select v-model="form.locality.brazilStateId" required :disabled="!form.locality.countryId" @change="loadMunicipalities"><option disabled value="">{{ form.locality.countryId ? 'Selecione' : 'Selecione primeiro o país' }}</option><option v-for="item in states" :key="item.id" :value="item.id">{{ item.abbreviation }} · {{ item.name }}</option></select></label><label>Município<select v-model="form.locality.brazilMunicipalityId" required :disabled="!form.locality.brazilStateId"><option disabled value="">{{ form.locality.brazilStateId ? 'Selecione' : 'Selecione primeiro o estado' }}</option><option v-for="item in municipalities" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></template></div></div>
        </section>
        <section><h4>Definição de recorrência</h4><div class="recurrence"><label>Tipo de recorrência<select :value="form.recurrence.type" @change="changeRecurrenceType(($event.target as HTMLSelectElement).value as RecurrenceType)"><option value="ANNUAL_FIXED_DATE">Anual em data fixa</option><option value="ONE_TIME_DATE">Data única</option><option value="ANNUAL_NTH_WEEKDAY">Dia ordinal da semana</option><option value="EASTER_OFFSET">Deslocamento da Páscoa</option></select></label><label v-if="form.recurrence.type === 'ONE_TIME_DATE'">Data da ocorrência<input v-model="form.recurrence.oneTimeDate" type="date" required></label><div v-if="form.recurrence.type === 'ANNUAL_FIXED_DATE'" class="date-pair" role="group" aria-label="Dia e mês"><label>Dia<select v-model.number="form.recurrence.fixedDay" required><option disabled value="">DD</option><option v-for="day in 31" :key="day" :value="day">{{ day }}</option></select></label><span>/</span><label>Mês<select v-model.number="form.recurrence.fixedMonth" required><option disabled value="">MM</option><option v-for="month in 12" :key="month" :value="month">{{ month }}</option></select></label></div><div v-if="form.recurrence.type === 'ANNUAL_NTH_WEEKDAY'" class="ordinal"><label>Mês<select v-model.number="form.recurrence.weekMonth"><option v-for="month in 12" :key="month" :value="month">{{ month }}</option></select></label><label>Ocorrência<select v-model="form.recurrence.weekOrdinal"><option value="FIRST">Primeira</option><option value="SECOND">Segunda</option><option value="THIRD">Terceira</option><option value="FOURTH">Quarta</option><option value="FIFTH">Quinta</option><option value="LAST">Última</option></select></label><label>Dia da semana<select v-model="form.recurrence.weekDay"><option value="MONDAY">Segunda-feira</option><option value="TUESDAY">Terça-feira</option><option value="WEDNESDAY">Quarta-feira</option><option value="THURSDAY">Quinta-feira</option><option value="FRIDAY">Sexta-feira</option><option value="SATURDAY">Sábado</option><option value="SUNDAY">Domingo</option></select></label></div><div v-if="form.recurrence.type === 'EASTER_OFFSET'" class="offset"><label>Deslocamento em dias da Páscoa<span class="offset-control"><input v-model.number="form.recurrence.easterOffsetDays" type="number" step="1"><IconButton label="Ajuda sobre deslocamento da Páscoa" :aria-expanded="easterHelpOpen" @click="easterHelpOpen = !easterHelpOpen"><img :src="icon('help')" alt=""></IconButton></span></label><aside v-if="easterHelpOpen" role="note"><img :src="icon('help')" alt="">Paixão de Cristo −2, Carnaval −48 e Corpus Christi +60.</aside></div></div></section>
        <section><h4>Vigência</h4><div class="grid"><label>Início da vigência<input v-model="form.validity.from" type="date"></label><label>Fim da vigência<input v-model="form.validity.to" type="date"></label></div></section>
      </fieldset><footer><button class="ui-button ui-button--destructive" type="button" @click="emit('cancel')">Cancelar</button><button class="ui-button ui-button--primary" type="submit" :disabled="saving">{{ saving ? 'Salvando…' : 'Salvar' }}</button></footer></div>
    </form>
  </section>
</template>

<style scoped>
.calendar-occasion-form,form,.frame{display:flex;flex-direction:column;min-height:0}.calendar-occasion-form{height:100%;overflow:hidden}.calendar-occasion-form>header{padding:var(--space-3) var(--space-4);border-bottom:var(--component-border-width) solid var(--color-border-subtle)}h3,h4{margin:0;color:var(--color-text-primary)}h3{font-size:var(--font-size-lg)}form,.frame{flex:1}.feedback{margin:var(--space-3) var(--space-4) 0}.feedback p,.feedback ul{margin:0}.frame{gap:var(--space-3);padding:var(--component-workspace-surface-padding);overflow:hidden}fieldset{display:grid;flex:1;align-content:start;gap:var(--space-6);min-height:0;margin:0;padding:var(--space-4);overflow:auto;border:var(--component-border-width) solid var(--color-border-subtle);border-radius:var(--radius-md);background:var(--color-surface-raised)}section{display:grid;gap:var(--space-3)}h4{display:flex;align-items:center;gap:var(--space-3);font-size:var(--font-size-sm);font-weight:var(--font-weight-bold);letter-spacing:var(--letter-spacing-wide);text-transform:uppercase}h4::after{height:calc(var(--component-border-width) * 2);flex:1;background:var(--color-border-subtle);content:''}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3)}.recurrence{display:grid;grid-template-columns:minmax(13rem,1fr) repeat(3,minmax(0,1fr));gap:var(--space-3)}label{display:grid;gap:var(--space-1)}input,select{width:100%;min-height:var(--control-height-sm);padding:var(--space-2) var(--space-3);border:var(--component-border-width) solid var(--color-border-subtle);border-radius:var(--radius-sm);background:var(--color-surface-raised);color:var(--color-text-primary);font:inherit}.locality-slot{display:flex;flex-wrap:wrap;gap:var(--space-3);min-height:calc(var(--control-height-md) + var(--font-size-sm) + var(--space-1))}.locality-slot>label{flex:1 1 10rem}.locality-slot:empty{background:transparent}.date-pair{display:flex;align-items:end;gap:var(--space-2)}.date-pair label{width:4.75rem}.date-pair>span{padding-bottom:var(--space-2);font-weight:var(--font-weight-bold)}.ordinal{display:grid;grid-column:span 3;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-3)}.offset{position:relative;grid-column:span 3}.offset-control{display:flex;overflow:hidden;border:var(--component-border-width) solid var(--color-border-subtle);border-radius:var(--radius-sm)}.offset-control input{min-width:0;flex:1;border:0;border-radius:0}.offset-control .ui-icon-button{border:0;border-left:var(--component-border-width) solid var(--color-border-subtle);border-radius:0}.offset img{width:var(--icon-size-sm);height:var(--icon-size-sm);object-fit:contain}.offset aside{position:absolute;z-index:2;top:calc(100% + var(--space-2));right:0;display:flex;width:min(22rem,100%);gap:var(--space-2);padding:var(--space-3);border:var(--component-border-width) solid var(--color-action-primary);border-radius:var(--radius-md);background:color-mix(in srgb,var(--color-action-primary) var(--color-mix-subtle),var(--color-surface-raised));box-shadow:var(--shadow-float);font-size:var(--font-size-sm)}footer{display:flex;justify-content:end;gap:var(--space-2)}@media(max-width:700px){.grid,.recurrence,.ordinal{grid-template-columns:1fr}.ordinal,.offset{grid-column:auto}.locality-slot{min-height:0}input,select{font-size:max(1rem,16px)}}
</style>
